228	        }
229	        RollupService.Snapshot before = rollup.snapshot(sheetId);
230	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
231	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
232	        ClaimStatus was = claim.getStatus();
233	        // only a steward's review moves a PENDING claim on, other than voiding it
234	        if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))) {
235	            throw new ResponseStatusException(HttpStatus.CONFLICT,
236	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
237	        }
238	        periods.refuseIfClosed(sheetId, claim.getDate());
239	        boolean reversing = was == ClaimStatus.SETTLED;
240	        if (reversing) {
241	            refuseVoidSettled(sheetId, user, claim);
242	        }
243	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
244	            throw new ResponseStatusException(HttpStatus.CONFLICT,
245	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then.");
246	        }
247	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
248	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
249	                    "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
250	        }
251	        if (review && !isSteward(sheetId, user)) {
252	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
253	                    "Only a steward can approve or reject a PENDING claim.");
254	        }
255	        Person person = person(sheetId, claim.getPersonId());
256	        // settling fixes the figure with its late charge as it stands on the sheet's today (a
