392	        Person person = person(sheetId, claim.getPersonId());
393	        BigDecimal old = claim.getSettledDue();
394	        BigDecimal settling = LateCharge.withChargeAsOpen(sheets.sheet(sheetId), claim, due(sheetId, person, claim));
395	        claim.setSettledDue(settling);
396	        logStatus(sheetId, user, person, claim);
397	        Claim saved = claims.saveAndFlush(claim);
398	        audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
399	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
400	                + " old=" + dueText(old) + " new=" + dueText(settling));
401	        notifyWatchers(sheetId, user, person, saved);
402	        rollup.recordChanges(sheetId, user, before);
403	        return saved;
404	    }
405	
406	    /**
407	     * Move a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and
408	     * date, is unbound from any statement (live again until its new person's next statement), and
409	     * is listed first under its new person. Refused (403) for a role the permission matrix does not allow, (409) for a SETTLED or VOID
410	     * claim or a move to the person it is already on, (400) for a correction (it must stay with
411	     * the claim it corrects), (423) when dated inside a closed period and (422) when dated after
412	     * the new person's retirement date.
413	     */
414	    @Transactional
415	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
416	        roles.refuseUnlessPermitted(sheetId, user, "reassign");
417	        RollupService.Snapshot before = rollup.snapshot(sheetId);
418	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
419	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
420	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
421	            throw new ResponseStatusException(HttpStatus.CONFLICT,
422	                    "A " + claim.getStatus() + " claim cannot be moved.");
423	        }
424	        Person from = person(sheetId, claim.getPersonId());
425	        Person to = person(sheetId, toPersonId);
426	        if (from.getId().equals(to.getId())) {
427	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already on that person.");
428	        }
429	        if (claim.isCorrection()) {
430	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A correction cannot be moved.");
431	        }
432	        periods.refuseIfClosed(sheetId, claim.getDate());
433	        refuseIfRetired(to, claim.getDate());
434	        claim.setPersonId(to.getId());
435	        claim.bind(false, null);
436	        claims.saveAndFlush(claim);
437	        claims.listFirst(claim.getId());
438	        Claim saved = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
439	        audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
440	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
441	                + " from=" + from.getName() + " to=" + to.getName());
442	        rollup.recordChanges(sheetId, user, before);
443	        return saved;
444	    }
445	
446	    /** What a split did: the original claim, keeping the rest of its amount, and the new claim split off it. */
447	    public record Split(Claim original, Claim split) {
448	    }
449	
450	    /**
451	     * Split an amount off an OPEN claim: the claim keeps the rest of its amount and is unbound from
452	     * any statement; a new OPEN claim with the amount split off, the same date and note, the next
453	     * number, opened by the user and due by its date plus the terms in force on it, is listed first
454	     * under the person and shows the original's number as split-from. Refused (403) for a role that
455	     * may not open a claim, (409) for a claim that is not OPEN or is deferred, (400) for an amount
456	     * not above 0.00 and below the claim's, and (423) when dated inside a closed period.
457	     */
458	    @Transactional
459	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
460	        roles.refuseViewer(sheetId, user);
461	        roles.refuseUnlessPermitted(sheetId, user, "open");
462	        // lock the sheet's numbering before reading the claim, as opening one does
463	        sheets.lock(sheetId);
464	        RollupService.Snapshot before = rollup.snapshot(sheetId);
465	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
466	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
467	        if (claim.getStatus() != ClaimStatus.OPEN) {
468	            throw new ResponseStatusException(HttpStatus.CONFLICT,
469	                    "A " + claim.getStatus() + " claim cannot be split.");
470	        }
471	        if (claim.isDeferredOn(sheets.today(sheetId))) {
472	            throw new ResponseStatusException(HttpStatus.CONFLICT,
473	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be split before then.");
474	        }
475	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
476	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
477	                    "A split must be more than 0.00 and less than the claim's amount.");
478	        }
479	        periods.refuseIfClosed(sheetId, claim.getDate());
480	        Person person = person(sheetId, claim.getPersonId());
481	        claim.setAmount(claim.getAmount().subtract(amount));
482	        claim.bind(false, null);
483	        Claim original = claims.saveAndFlush(claim);
484	        LocalDate dated = claim.getDate();
485	        Claim split = new Claim(sheetId, person.getId(), amount, dated,
486	                dueBy(sheetId, person, dated), claim.getNote(), null);
487	        split.setStatus(ClaimStatus.OPEN);
488	        split.setNumber(sheets.nextClaimNumber(sheetId, dated));
489	        split.setOpenedBy(user);
490	        split.setSplitFrom(original.getNumber());
491	        logStatus(sheetId, user, person, split);
492	        Claim added = claims.saveAndFlush(split);
493	        audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original)
494	                + " number=" + original.getNumber() + " into=" + added.getNumber());
495	        audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, added) + " number=" + added.getNumber());
496	        rollup.recordChanges(sheetId, user, before);
497	        return new Split(original, added);
498	    }
499	
500	    /** What a bulk open did: how many claims were opened and how many refused, and the claims opened. */
501	    public record BulkOpened(int opened, int refused, List<Claim> claims) {
502	    }
503	
504	    /**
505	     * Open the given claims together, in list order (the order people were added, newest claim
506	     * first within a person), so they are numbered in that order. A claim that cannot be opened
507	     * (not on the sheet, not DRAFT, or dated inside a closed period) is refused and left as it is.
508	     */
509	    @Transactional
510	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> ids) {
511	        List<Claim> selected = inListOrder(sheetId, ids);
512	        int refused = (int) ids.stream().distinct().count() - selected.size();
513	        List<Claim> opened = new ArrayList<>();
514	        boolean permitted = sheets.sheet(sheetId).permits("open", roles.roleOf(sheetId, user));
515	        for (Claim claim : selected) {
516	            if (!permitted || claim.getStatus() != ClaimStatus.DRAFT || periods.isClosed(sheetId, claim.getDate())) {
517	                refused++;
518	                continue;
519	            }
520	            opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
521	        }
522	        return new BulkOpened(opened.size(), refused, opened);
523	    }
524	
525	    /** What a bulk settle did: how many claims were settled (or made PENDING) and how many refused, and the claims changed. */
526	    public record BulkSettled(int settled, int refused, List<Claim> claims) {
527	    }
528	
529	    /**
530	     * Settle the given claims together, in list order (the order people were added, newest claim
531	     * first within a person), each by exactly the rules of settling one claim. A claim a clerk's
532	     * settle makes PENDING counts as settled; a claim that cannot be settled is refused and left
533	     * as it is.
534	     */
535	    @Transactional
536	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> ids) {
537	        List<Claim> selected = inListOrder(sheetId, ids);
538	        int refused = (int) ids.stream().distinct().count() - selected.size();
539	        List<Claim> settled = new ArrayList<>();
540	        for (Claim claim : selected) {
541	            try {
542	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
543	            } catch (ResponseStatusException refusedOne) {
544	                // every refusal is checked before the claim is changed, so it is left as it is
545	                refused++;
546	            }
547	        }
548	        return new BulkSettled(settled.size(), refused, settled);
549	    }
550	
551	    /** The given claims on the sheet in list order: people as added, newest claim first within a person. */
552	    private List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
553	        Map<Long, Integer> personOrder = new HashMap<>();
554	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
555	        for (int i = 0; i < listed.size(); i++) {
556	            personOrder.put(listed.get(i).getId(), i);
557	        }
558	        return ids.stream().distinct()
559	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
560	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
561	                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
562	                .toList();
563	    }
564	
565	    /**
566	     * The due on a claim's amount at the rate for the person's grade in force on the claim's date,
567	     * rounded to the cent as the claim rounds (see {@link Rounding}), not raised to the floor (see {@link LateCharge});
568	     * null with no rate in force then.
569	     */
570	    public BigDecimal due(String sheetId, Person person, Claim claim) {
571	        Sheet sheet = sheets.sheet(sheetId);
572	        RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
573	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
574	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding))
575	                .orElse(null);
576	    }
577	
578	    /** The date a claim rounds by: its own, or for a correction that of the claim it corrects. */
579	    private LocalDate roundingDate(String sheetId, Claim claim) {
580	        if (!claim.isCorrection() || claim.getCorrects() == null) {
581	            return claim.getDate();
582	        }
583	        return Rounding.dateOf(claim, claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()));
584	    }
585	
586	    /** Log the claim's status as it is now: by the user, on the sheet's today, with its due as computed now. */
587	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
588	        claim.log(new ClaimLogEntry(claim.getStatus(), user, sheets.today(sheetId),
589	                dueText(charged(sheetId, person, claim))));
590	    }
591	
592	    private static String dueText(BigDecimal due) {
593	        return due == null ? "n/a" : due.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
594	    }
595	
596	    /** Whether a claim settling at the figure is above the proof threshold in force on its date and has no proofs. */
597	    private boolean needsProof(String sheetId, Claim claim, BigDecimal figure) {
598	        BigDecimal threshold = sheets.sheet(sheetId).proofThresholdOn(claim.getDate());
599	        return claim.getProofs() == 0 && figure != null && threshold != null && figure.compareTo(threshold) > 0;
600	    }
601	
602	    /** Whether the user is a clerk settling a claim whose figure is above the sheet's clerk limit. */
603	    private boolean aboveClerkLimit(String sheetId, String user, BigDecimal figure) {
604	        BigDecimal limit = sheets.clerkLimit(sheetId);
605	        return figure != null && limit != null && figure.compareTo(limit) > 0 && !isSteward(sheetId, user);
606	    }
607	
608	    private boolean isSteward(String sheetId, String user) {
609	        return Role.STEWARD.equals(roles.roleOf(sheetId, user));
610	    }
611	
612	    /**
613	     * The number a claim corrects: none unless its amount is negative, when it must name the number
614	     * of a SETTLED claim of the same person, else it is refused (400).
615	     */
616	    private String corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
617	        if (amount.signum() >= 0) {
618	            return null;
619	        }
620	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
621	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
622	        if (!settled) {
623	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
624	                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
625	        }
626	        return corrects;
627	    }
628	
629	    /** Refuse (422) a claim dated after its person's retirement date. */
630	    private static void refuseIfRetired(Person person, LocalDate date) {
631	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
632	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
633	                    "That claim's date is after its person's retirement date.");
634	        }
635	    }
636	
637	    private Person person(String sheetId, long personId) {
638	        return people.findByIdAndSheetId(personId, sheetId)
639	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
640	    }
641	
642	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
643	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName() + " amount="
644	                + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString() + " date=" + claim.getDate();
645	    }
646	
647	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
648	        return date != null ? date : sheets.today(sheetId);
649	    }
650	}
